package dev.underthebedrock.horror;
import org.junit.jupiter.api.Test;import java.util.Set;import static org.junit.jupiter.api.Assertions.*;
class LorePersistenceTest {
 @Test void loreAndRecordingDiscoveriesAreIndependentAndPersistentInMemoryModel(){PlayerHorrorMemory memory=new PlayerHorrorMemory();assertTrue(memory.discoverLore("architects"));assertFalse(memory.discoverLore("architects"));assertTrue(memory.hearRecording("first_blueprint"));assertFalse(memory.hearRecording("first_blueprint"));assertTrue(memory.hasLore("architects"));memory.discoverLore("architect_seal");assertTrue(memory.hasLore("architect_seal"));assertTrue(memory.hasRecording("first_blueprint"));assertEquals(1,memory.loreCount());assertEquals(Set.of("first_blueprint"),memory.heardRecordings());}
 @Test void legacyRestoreWithoutLoreRemainsValid(){PlayerHorrorMemory memory=new PlayerHorrorMemory();memory.restore(0,0,0,0,0,0,0,0,"none",null,Set.of("first_signal"),"first_signal",0,Set.of(),Set.of());assertTrue(memory.hasClue("first_signal"));assertEquals(0,memory.loreCount());}
 @Test void lateGameIdentityRequiresFactionTestimoniesAndIdentityRecording(){PlayerHorrorMemory memory=new PlayerHorrorMemory();for(String faction:new String[]{"architects","researchers","keepers","witnesses"})memory.discoverLore(faction);assertFalse(memory.hasRecording("identity_fragment"));assertTrue(memory.hearRecording("identity_fragment"));assertTrue(memory.hasLore("architects")&&memory.hasLore("researchers")&&memory.hasLore("keepers")&&memory.hasLore("witnesses"));}
}